"""Partition-quality comparison across methods (MPI).

For each method, partitions the source elements at the current world size
and reports the metrics that drive dist-gnn's runtime communication cost:

- halo classes:  unique gids whose copies span >1 rank (each needs a halo
  swap every message-passing layer)
- halo copies:   total node copies belonging to halo classes
- neighbors:     max/mean over ranks of the number of distinct ranks a rank
  shares at least one gid with
- imbalance:     max/mean element count over ranks

Usage (any M; source generated by gen_synthetic.py or real gnn_outputs):

    mpirun -n M python repartition/tests/partition_quality.py \
        --src /tmp/synth --methods block rcb parrsb

Gathers (gid, dest) pairs to rank 0 — fine at test scale.
"""

# ruff: file-ignore[module-import-not-at-top-of-file]  # imports follow sys.path setup

import argparse
import os
import sys

import numpy as np
from mpi4py import MPI

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.abspath(os.path.join(HERE, "..", "..")))

from repartition.partition import partition_elements
from repartition.sources import BinSource


def quality(elems, dest, comm):
    """Metrics tuple on rank 0 (see module docstring), None elsewhere."""
    ne = elems.n_elements
    g = elems.gids.reshape(ne, elems.Np)
    d = np.broadcast_to(dest[:, None], g.shape)
    shared = g != 0  # gid==0 nodes never participate in a gather
    pairs = np.unique(np.stack([g[shared], d[shared]], axis=1), axis=0)

    all_pairs = comm.gather(pairs, root=0)
    all_ne = np.array(comm.gather(ne, root=0) or [0])
    if comm.Get_rank() != 0:
        return None

    size = comm.Get_size()
    # (gid, rank) pairs, deduped across ranks
    p = np.unique(np.concatenate(all_pairs), axis=0)
    gid, rk = p[:, 0], p[:, 1]
    order = np.argsort(gid, kind="stable")
    gid, rk = gid[order], rk[order]
    _, start, counts = np.unique(gid, return_index=True, return_counts=True)
    multi = counts > 1
    halo_classes = int(multi.sum())
    halo_copies = int(counts[multi].sum())

    nbrs = [set() for _ in range(size)]
    for s, c in zip(start[multi], counts[multi], strict=True):
        ranks = rk[s : s + c]
        for a in ranks:
            nbrs[a].update(ranks)
    nnbr = np.array([len(n - {i}) for i, n in enumerate(nbrs)])

    ne_counts = np.bincount(
        np.concatenate([np.full(n, i) for i, n in enumerate(all_ne)]),
        minlength=size,
    )
    return (
        halo_classes,
        halo_copies,
        int(nnbr.max()),
        float(nnbr.mean()),
        int(ne_counts.max()),
        float(ne_counts.mean()),
    )


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--src", required=True)
    ap.add_argument("--methods", nargs="+", default=["block", "rcb", "parrsb"])
    args = ap.parse_args()

    comm = MPI.COMM_WORLD
    src = BinSource(args.src)
    elems, _ = src.read_elements(comm)

    results = {}
    for method in args.methods:
        dest = partition_elements(elems, comm, method=method)
        results[method] = quality(elems, dest, comm)

    if comm.Get_rank() == 0:
        print(f"world size M={comm.Get_size()}, src={args.src}")
        cols = ["method", "halo_cls", "halo_cp", "nbr_max",
                "nbr_mean", "ne_max", "ne_mean"]
        print(" ".join(f"{c:>9}" for c in cols))
        for method, q in results.items():
            hc, hcp, nm, nmean, nem, nemean = q
            row = [method, hc, hcp, nm, f"{nmean:.2f}", nem, f"{nemean:.2f}"]
            print(" ".join(f"{v:>9}" for v in map(str, row)))


if __name__ == "__main__":
    main()
